export default async function plan({ spreadsheetId }, context) {
  let state = await context.state.get("reply-feedback-sheet");
  if (spreadsheetId) return { ready: true, spreadsheetId, title: "Sheet1" };
  if (state?.pending)
    throw Error(
      "Spreadsheet creation outcome is pending; inspect Google Sheets and configure the spreadsheet ID",
    );
  if (state?.spreadsheetId && state?.title)
    return { ready: true, spreadsheetId: state.spreadsheetId, title: state.title };
  await context.state.set("reply-feedback-sheet", { pending: true });
  return { ready: false, spreadsheetId: "", title: "" };
}

