export default function created({ spreadsheetId, sheets }) {
  const title = sheets?.[0]?.properties?.title;
  if (typeof spreadsheetId !== "string" || !spreadsheetId || typeof title !== "string" || !title)
    throw Error("Spreadsheet or default worksheet missing");
  return { spreadsheetId, title, range: "'" + title.replace(/'/g, "''") + "'!A1:D1" };
}

