export default async function save({ existing, existingTitle, created, createdTitle }, context) {
  const id = existing || created,
    title = existing ? existingTitle : createdTitle;
  if (!id || !title) throw Error("Missing spreadsheet or worksheet");
  if (!existing) await context.state.set("reply-feedback-sheet", { spreadsheetId: id, title });
  const base = "'" + title.replace(/'/g, "''") + "'!";
  return { spreadsheetId: id, title, allRange: base + "A:D", idRange: base + "A:A" };
}

